import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 전표(journal_entry.expense_resolution_id)에 연결할 결의서 ID의 출처가 정해지지 않았다.
// 스펙에 출처가 없어 임시 상수로 두며, 실제 값은 사람이 정해야 한다.
const PAYROLL_EXPENSE_RESOLUTION_ID = 1;

// 가정: 급여구분(payroll_run) 코드를 계정 설정의 급여 구분 이름으로 바꾼다.
const PAYROLL_TYPE_NAME: Record<string, string> = {
  REGULAR: '상용직',
  DAILY: '일용직',
  SEVERANCE: '퇴직금',
};

@Controller('api/v1')
export class FnSfr02110Controller {
  @Post('/payroll-runs/:payrollRunId/create-journal-entry')
  @HttpCode(200)
  async createPayrollJournalEntry(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const runId = req.params['payrollRunId'];
    if (!/^\d+$/.test(runId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '급여 지급일 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const runs = await db.query(
        'SELECT payroll_run_id, payroll_type, is_closed, journal_status FROM payroll_run WHERE payroll_run_id = CAST(:runId AS bigint) FOR UPDATE',
        { runId },
      );
      if (runs.length === 0) {
        throw new ApiError(404, 'PAYROLL_RUN_NOT_FOUND', '급여 지급일을 찾을 수 없습니다.');
      }
      const run = runs[0];
      if (!run.is_closed) {
        throw new ApiError(409, 'PAYROLL_NOT_CLOSED', '마감되지 않은 급여는 전표처리할 수 없습니다.');
      }
      if (run.journal_status === 'PROCESSED') {
        throw new ApiError(409, 'JOURNAL_ALREADY_PROCESSED', '이미 전표처리된 급여입니다.');
      }
      const typeName = PAYROLL_TYPE_NAME[String(run.payroll_type)];
      const mappings = await db.query(
        "SELECT payroll_account_mapping_id FROM payroll_account_mapping WHERE payroll_type = :typeName AND is_active = '사용'",
        { typeName },
      );
      if (mappings.length === 0) {
        throw new ApiError(
          422,
          'ACCOUNT_MAPPING_MISSING',
          '계정과목 매핑이 없습니다. 누락 항목: 급여 구분 ' + typeName,
        );
      }
      const resolutions = await db.query(
        'SELECT expense_resolution_id FROM expense_resolution WHERE expense_resolution_id = CAST(:erId AS bigint)',
        { erId: PAYROLL_EXPENSE_RESOLUTION_ID },
      );
      if (resolutions.length === 0) {
        throw new ApiError(422, 'ACCOUNT_MAPPING_MISSING', '전표에 연결할 결의서가 없어 전표를 생성할 수 없습니다.');
      }
      // 가정: 급여 금액은 암호문(_enc)으로만 저장되어 합계를 산출할 수 없으므로 0으로 둔다.
      const created = await db.query(
        "INSERT INTO journal_entry (expense_resolution_id, entry_date, status, total_debit_amount, total_credit_amount, created_at, updated_at) VALUES (CAST(:erId AS bigint), CAST(now() AS date), '신청', 0, 0, now(), now()) RETURNING journal_entry_id AS \"journalEntryId\", to_char(entry_date, 'YYYY-MM-DD') AS \"entryDate\", total_debit_amount AS \"totalDebitAmount\", total_credit_amount AS \"totalCreditAmount\"",
        { erId: PAYROLL_EXPENSE_RESOLUTION_ID },
      );
      const entry = created[0];
      await db.execute(
        "UPDATE payroll_run SET journal_status = 'PROCESSED', journal_entry_id = CAST(:entryId AS bigint), updated_at = now() WHERE payroll_run_id = CAST(:runId AS bigint)",
        { entryId: entry.journalEntryId, runId },
      );
      return {
        journalEntryId: Number(entry.journalEntryId),
        entryDate: entry.entryDate,
        totalDebitAmount: Number(entry.totalDebitAmount),
        totalCreditAmount: Number(entry.totalCreditAmount),
        journalStatus: 'PROCESSED',
      };
    });
  }
}

