import { useState } from 'react';
import {
  Band,
  DataTable,
  DateText,
  Drawer,
  Badge,
  Field,
  Form,
  LookupSelect,
  Num,
  RefName,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr02110Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [payrollRunId, setPayrollRunId] = useState<number | string>('');
  const [selected, setSelected] = useState<Row | null>(null);

  const submit = async () => {
    if (payrollRunId === '') {
      throw new Error('전표처리할 급여 지급일을 선택해 주세요.');
    }
    const res = await call(
      'POST',
      '/payroll-runs/' + payrollRunId + '/create-journal-entry',
      role,
      {},
    );
    setResults([{ ...res, payrollRunId }, ...results]);
    setOpen(false);
    setPayrollRunId('');
    notify('급여 전표를 생성했습니다.');
  };

  if (selected) {
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>
          목록으로
        </button>
        <section className="box">
          <h2>급여 전표</h2>
          <Pairs
            items={[
              ['급여 지급일', <RefName table="payroll_run" role={role} value={selected.payrollRunId} />],
              ['전표 ID', <RefName table="journal_entry" role={role} value={selected.journalEntryId} />],
              ['전표 일자', <DateText value={selected.entryDate} />],
              ['차변 합계', <Num value={selected.totalDebitAmount} />],
              ['대변 합계', <Num value={selected.totalCreditAmount} />],
              ['전표처리 상태', <Badge value={selected.journalStatus} />],
            ]}
          />
        </section>
      </div>
    );
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>급여 전표처리</h2>
        <Band total={results.length}>
          <button onClick={() => setOpen(true)}>전표 생성</button>
        </Band>
        <DataTable
          columns={[
            {
              key: 'payrollRunId',
              label: '급여 지급일',
              render: (r) => <RefName table="payroll_run" role={role} value={r.payrollRunId} />,
            },
            { key: 'entryDate', label: '전표 일자', render: (r) => <DateText value={r.entryDate} /> },
            { key: 'totalDebitAmount', label: '차변 합계', render: (r) => <Num value={r.totalDebitAmount} /> },
            { key: 'totalCreditAmount', label: '대변 합계', render: (r) => <Num value={r.totalCreditAmount} /> },
            { key: 'journalStatus', label: '전표처리 상태', render: (r) => <Badge value={r.journalStatus} /> },
          ]}
          rows={results}
          onRowClick={(r) => setSelected(r)}
          empty="아직 전표처리한 내역이 없습니다. 전표 생성 버튼을 눌러 마감된 급여를 처리해 주세요."
        />
      </section>
      {open && (
        <Drawer title="급여 전표 생성" onClose={() => setOpen(false)}>
          <Form
            onSubmit={submit}
            submit="전표 생성"
            danger
            note="전표처리를 하면 해당 급여는 전표처리 완료 상태가 되고 다시 처리할 수 없습니다."
          >
            <Field label="급여 지급일" required wide>
              <LookupSelect
                table="payroll_run"
                role={role}
                value={payrollRunId}
                onChange={setPayrollRunId}
                placeholder="지급일 선택"
              />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
